pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // Open to public so wager() works
        c.OpenToThePublic();
        // Set betLimit to 100
        c.AdjustBetAmounts(100);
        // Now wager() requires msg.value == betLimit (100)
        vm.deal(address(this), 100);
        // This should succeed on reference (betLimit=100) but revert on bug (betLimit=0)
        bool ok;
        try c.wager{value: 100}() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

