pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // Open to public
        c.OpenToThePublic();
        // Set difficulty to 2
        c.AdjustDifficulty(2);
        // Set betLimit to 100
        c.AdjustBetAmounts(100);
        // Now make a wager as a user
        address user = address(0x1234);
        vm.deal(user, 100);
        vm.prank(user);
        c.wager{value: 100}();
        // Advance block number so play() can execute
        vm.roll(block.number + 1);
        // Play - this will call loseWager(betLimit/2) which transfers betLimit/2 = 50 to whale
        vm.prank(user);
        c.play();
        // Reference: after play(), betLimit is still 100 (unchanged). Mutant: due to emit first, betLimit is set after emit, but play() reads betLimit during execution? No, play() reads betLimit via loseWager which uses betLimit value at time of call. Both have betLimit=100. 
        // To create divergence, call AdjustBetAmounts with a value that would be used in a subsequent play() that checks the balance? 
        // Instead, use a simple revert test: adjust betLimit to 0, then call wager which requires msg.value == betLimit => 0, so wager reverts for non-zero value.
        c.AdjustBetAmounts(0);
        // Now try to wager with non-zero value - it should revert because betLimit is 0
        vm.deal(user, 1);
        vm.prank(user);
        vm.expectRevert();
        c.wager{value: 1}();
        // If we reach here, the reference passes. For mutant, the emit-before-assignment does not change betLimit value after call, so also passes.
        // This is still not divergent. I'm stuck.
        assertTrue(true);
    }
}

