// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // Deploy with whale = address(this), betLimit = 0 (so wagering requires small eth?)
        // Actually we need openToPublic, betLimit > 0
        // Step 1: open to public
        c.OpenToThePublic();
        // Step 2: adjust bet limit to 100 wei
        c.AdjustBetAmounts(100);
        // Step 3: a user donates 1 ether to get balance high
        address user = address(0x1234);
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.donate{value: 1 ether}();
        // Step 4: now adjust difficulty with amount = 100
        // In reference: difficulty becomes 100; in mutant: difficulty becomes 200
        c.AdjustDifficulty(100);
        // Now the key observable: winnersPot() depends on difficulty? No, it returns address(this).balance / 2
        // Actually need a different observable: play() checks blockNumber < block.number
        // We need a wagered user: let's wager and then play
        address player = address(0x5678);
        vm.deal(player, 100 wei);
        vm.prank(player);
        c.wager{value: 100}(); // wager stored block.number
        vm.roll(block.number + 1); // advance so blockNumber < block.number
        // Now play() uses difficulty; in reference difficulty = 100, winningNumber = hash % 100 + 1
        // difficulty/2 = 50, so win if winningNumber == 50
        // In buggy difficulty = 200, difficulty/2 = 100, so win if winningNumber == 100
        // Since hash is deterministic, one will win, other lose. But we need a concrete guarantee
        // We'll just check that after play, the winner's balance changes depending on difficulty.
        // Actually better: call play and check revert? No, we just observe balance change.
        // Let's compute hash: blockhash(block.number-1) and player => uint256 hash = uint256(keccak256(abi.encodePacked(blockhash(block.number-1), player))) % difficulty + 1
        // Since blockhash is unknown, we cannot precompute. But we can use a different approach:
        // revert difference on wager if betLimit invalid? No.
        // Actually the difference is that after AdjustDifficulty(100), reference difficulty=100, buggy=200.
        // So calling currentDifficulty() will return 100 vs 200.
        // That's observable and directly diverges.
        uint256 refDiff = c.currentDifficulty();
        assertTrue(refDiff == 100, "Buggy contract would make difficulty 200, breaking this assertion");
    }
}

