pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // Step 1: Open the contract to public
        vm.prank(address(this));
        c.OpenToThePublic();

        // Step 2: Adjust bet limit to 100 wei (so wager requires exactly 100 wei)
        c.AdjustBetAmounts(100);

        // Step 3: A user wagers exactly 100 wei
        address user = address(0x123);
        vm.deal(user, 100);
        vm.prank(user);
        c.wager{value: 100}();

        // Step 4: Adjust difficulty to 50 — reference sets difficulty=50, buggy sets difficulty=100
        c.AdjustBetAmounts(50);

        // Step 5: Donate 1 ether to increase balance and make payout possible
        vm.deal(address(0x456), 1 ether);
        vm.prank(address(0x456));
        c.donate{value: 1 ether}();

        // Step 6: Now play() for the wagerer
        vm.prank(user);
        c.play();

        // Assertion: In the reference, winningNumber = 25 (difficulty/2) so payout occurs, balance halved.
        // In buggy, difficulty=100, winningNumber != 50, so lose, balance stays.
        // The exact balance after play() differs:
        // Reference: initial balance = 1 ether + 100 wei, after payout half is sent, so address(this).balance = (1 ether + 100 wei) / 2
        // Buggy: after lose, half of betLimit/2 is sent (but careful: loseWager sends betLimit/2 = 25 wei), so balance = 1 ether + 100 wei - 25 wei
        // Hardcode the expected reference balance:
        uint256 refBalance = (1 ether + 100) / 2; // after payout, half remains
        assertTrue(address(c).balance == refBalance, "bug: balance does not match reference after play");
    }
}

