pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // Step 1: Deploy with betLimit = 100, but first need to set difficulty via AdjustDifficulty (onlyOwner)
        // We'll call AdjustDifficulty(100) -> reference difficulty = 100, buggy difficulty = 200
        vm.prank(address(this));
        c.AdjustDifficulty(100);

        // Step 2: open to public
        vm.prank(address(this));
        c.OpenToThePublic();

        // Step 3: AdjustBetAmounts(100) to set wager amount to 100
        vm.prank(address(this));
        c.AdjustBetAmounts(100);

        // Step 4: A user wagers exactly 100 wei
        address user = address(0x1234);
        vm.deal(user, 100);
        vm.prank(user);
        c.wager{value: 100}();

        // Step 5: Compute the winningNumber for this user with block.number at wager time
        // We need winningNumber == difficulty / 2 to trigger payout.
