        // In reference: player wins, so whale gets nothing from loseWager (whaleBalance unchanged)
        // In mutant: player loses, so whale gets betLimit/2 = 0.5 ether (whaleBalance increases)
        assertTrue(whaleAfter == whaleBefore + 0.5 ether, "Whale balance should increase by 0.5 ether on mutant");
    }
}

