pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // Open to public
        c.OpenToThePublic();
        // Set difficulty to 2
        c.AdjustDifficulty(2);
        // Set betLimit to 1 ether
        c.AdjustBetAmounts(1 ether);
        // Fund the player (address(this)) with 1 ether
        vm.deal(address(this), 1 ether);
        // Player wagers 1 ether
        c.wager{value: 1 ether}();
        // Player plays
        vm.warp(block.number + 1); // ensure block.number > timestamp block
        c.play();
        // Check whale's balance (the contract itself since address(this) was set as whale in constructor)
        // Reference: player wins => whale gets nothing from loseWager => balance = 0
        // Mutant: player loses => whale gets betLimit/2 = 0.5 ether => balance = 0.5 ether
        assertTrue(address(this).balance == 0.5 ether);
    }
}
